{"command": "cd /workspace/build && cat > gen_patterns.py << 'EOF'
import json

# note numbers (XM: C-1=0)
A2,C3,E3,G2,F2,B2,D3 = 33,36,40,31,29,34,38
A3,C4,E4,G3,F3,B3,D4 = 45,48,52,43,41,46,50
A4,C5,E5,G4,F4,B4,D5 = 57,60,64,55,53,58,62
F5,A5,G5,C6 = 65,69,68,72

CH = {  # chord -> dict
 'Am': dict(r2=33,r3=45,r4=57,t3=48,f3=52, pad=[45,48,52], pad2=[33,40]),
 'F' : dict(r2=29,r3=41,r4=53,t3=45,f3=48, pad=[41,45,48], pad2=[29,36]),
 'C' : dict(r2=36,r3=48,r4=60,t3=52,f3=55, pad=[48,52,55], pad2=[36,43]),
 'G' : dict(r2=31,r3=43,r4=55,t3=46,f3=50, pad=[43,46,50], pad2=[31,38]),
}
PROG = ['Am','F','C','G']

# channels
KICK,SNARE,HAT,OPENHAT,BASS,SUB,ARP,ARP2,LEAD,LEAD2,PAD,PAD2,RISER,IMPACT,FXP,FXS = range(16)
INST = {c:c+1 for c in range(16)}

# cell volumes
VOL = {KICK:64,SNARE:56,HAT:32,OPENHAT:36,BASS:56,SUB:52,ARP:40,ARP2:30,
       LEAD:40,LEAD2:40,PAD:36,PAD2:32,RISER:28,IMPACT:56,FXP:36,FXS:32}

cells = []  # (pattern,row,channel,note,instrument,volume,effect,effect_param)
def put(p,row,ch,note,vol=None,effect=0,param=0):
    cells.append((p,row,ch,note,INST[ch],vol if vol is not None else VOL[ch],effect,param))

def bass8(p,bar,chord):
    d=CH[chord]; r2,r3=d['r2'],d['r3']
    seq=[r2,r2,r3,r2,r2,r3,r2,r2]
    for i,n in enumerate(seq):
        put(p,bar*16+i*2,BASS,n)

def arp16(p,bar,chord):
    d=CH[chord]; r3,t3,f3,r4=d['r3'],d['t3'],d['f3'],d['r4']
    seq=[r3,t3,f3,r4,f3,t3,r3,t3,f3,r4,f3,t3,r3,t3,f3,r4]
    for i,n in enumerate(seq):
        put(p,bar*16+i,ARP,n)

def arp16b(p,bar,chord):
    d=CH[chord]; r3,t3,f3,r4=d['r3'],d['t3'],d['f3'],d['r4']
    seq=[r3,t3,f3,r4,f3,t3,r3,t3,f3,r4,f3,t3,r3,t3,f3,r4]
    for i,n in enumerate(seq):
        put(p,bar*16+i,ARP2,n)

def drums_std(p,bar):
    for r in (0,6,8,14): put(p,bar*16+r,KICK,0)
    for r in (4,12): put(p,bar*16+r,SNARE,0)
    for r in range(0,16,2): put(p,bar*16+r,HAT,0)
    for r in (6,14): put(p,bar*16+r,OPENHAT,0)

def drums_build(p,bar):
    for r in (0,6,8,14): put(p,bar*16+r,KICK,0)
    for r in (4,12): put(p,bar*16+r,SNARE,0)
    for r in range(16): put(p,bar*16+r,HAT,0)
    for r in (2,6,10,14): put(p,bar*16+r,OPENHAT,0)

def drums_half(p,bar):
    for r in (0,8): put(p,bar*16+r,KICK,0)
    put(p,bar*16+8,SNARE,0)
    for r in range(0,16,2): put(p,bar*16+r,HAT,0)

def padchord(p,bar,chord):
    for i,n in enumerate(CH[chord]['pad']):
        put(p,bar*16,PAD,n)
def pad2chord(p,bar,chord):
    for i,n in enumerate(CH[chord]['pad2']):
        put(p,bar*16,PAD2,n)
def subroot(p,bar,chord,rows=(0,)):
    for r in rows:
        put(p,bar*16+r,SUB,CH[chord]['r2'])

# lead melody (drop)
LEADM = {
 0:[(0,57),(4,64),(6,60),(8,57),(12,64),(14,60)],
 1:[(0,53),(4,60),(6,57),(8,53),(12,60),(14,57)],
 2:[(0,60),(4,68),(6,64),(8,60),(12,68),(14,64)],
 3:[(0,55),(4,62),(6,58),(8,55),(12,62),(14,58)],
 4:[(0,57),(4,60),(6,64),(8,69)],
 5:[(0,53),(4,57),(6,60),(8,65)],
 6:[(0,60),(4,64),(6,68),(8,72)],
 7:[(0,55),(4,58),(6,62),(8,68)],
}
LEAD2M = {
 4:[(0,45),(4,48),(6,52),(8,57)],
 5:[(0,41),(4,45),(6,48),(8,53)],
 6:[(0,48),(4,52),(6,55),(8,60)],
 7:[(0,43),(4,46),(6,50),(8,55)],
}
BRIDGE_LEAD = {
 0:[(0,57),(8,64)],
 1:[(0,53),(8,60)],
 2:[(0,60),(8,68)],
 3:[(0,55),(8,62)],
}

def lead_notes(p,bar,table,vol=40,slide=False):
    for (r,n) in table[bar]:
        eff = 0x0C if (slide and r==0) else 0
        par = 0x0C if (slide and r==0) else 0
        put(p,bar*16+r,LEAD,n,vol=vol,effect=eff,param=par)

# ---------------- P0 INTRO (4 bars) ----------------
for b in range(4):
    c=PROG[b]
    padchord(0,b,c); pad2chord(0,b,c); arp16(0,b,c); subroot(0,b,c,(0,))
    put(0,b*16,FXP,CH[c]['r4'])

# ---------------- P1 VERSE (8 bars) ----------------
for b in range(8):
    c=PROG[b%4]
    bass8(1,b,c); arp16(1,b,c); drums_std(1,b); padchord(1,b,c); subroot(1,b,c,(0,8))

# ---------------- P2 BUILD (4 bars) ----------------
for b in range(4):
    c=PROG[b]
    bass8(2,b,c); arp16(2,b,c); arp16b(2,b,c); drums_build(2,b); padchord(2,b,c)
put(2,32,RISER,0)

# ---------------- P3 DROP (8 bars) ----------------
for b in range(8):
    c=PROG[b%4]
    bass8(3,b,c); arp16(3,b,c); drums_std(3,b); padchord(3,b,c); subroot(3,b,c,(0,8))
    lead_notes(3,b,LEADM,slide=True)
    if b in (0,4): put(3,b*16,FXP,CH[c]['r4'])

# ---------------- P4 BRIDGE (4 bars) ----------------
for b in range(4):
    c=PROG[b]
    lead_notes(4,b,BRIDGE_LEAD,vol=48)
    padchord(4,b,c); pad2chord(4,b,c); subroot(4,b,c,(0,)); drums_half(4,b)
    d=CH[c]
    for i,n in enumerate([d['r3'],d['t3'],d['f3'],d['r4']]):
        put(4,b*16+i*4,ARP,n)

# ---------------- P5 DROP2 (8 bars) ----------------
for b in range(8):
    c=PROG[b%4]
    bass8(5,b,c); arp16(5,b,c); arp16b(5,b,c); drums_std(5,b); padchord(5,b,c); subroot(5,b,c,(0,8))
    lead_notes(5,b,LEADM,slide=True)
    if b in LEAD2M:
        for (r,n) in LEAD2M[b]:
            put(5,b*16+r,LEAD2,n)
    if b in (0,4): put(5,b*16,FXP,CH[c]['r4'])

# ---------------- P6 OUTRO (4 bars) ----------------
for b in range(4):
    c=PROG[b]
    padchord(6,b,c); pad2chord(6,b,c); arp16(6,b,c); subroot(6,b,c,(0,))
    if b in (0,1):
        for r in range(0,16,2): put(6,b*16+r,HAT,0)
put(6,0,FXS,0)
put(6,48,IMPACT,0)

# ---------------- build batch ----------------
lengths = {0:64,1:128,2:64,3:128,4:64,5:128,6:64}
batch=[]
for p,rows in lengths.items():
    batch.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":rows}})
for (p,row,ch,note,inst,vol,eff,par) in cells:
    a={"pattern":p,"row":row,"channel":ch,"note":note,"instrument":inst,"volume":vol}
    if eff: a["effect"]=eff; a["effect_param"]=par
    batch.append({"name":"pattern_set_cell","arguments":a})
json.dump(batch, open('batch_patterns.json','w'))
print('cells:',len(cells),'batch calls:',len(batch))
EOF
python3 gen_patterns.py"}

